import { Component, OnInit } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-employee-leave-status',
  templateUrl: './employee-leave-status.component.html',
  styleUrls: ['./employee-leave-status.component.css']
})
export class EmployeeLeaveStatusComponent implements OnInit {
  employeeId: number = 1;  // Example Employee ID (Can be dynamic)
  leaveRequests: any[] = [];

  constructor(private http: HttpClient) {}

  ngOnInit() {
    this.getEmployeeLeaveRequests();
  }

  getLeaveRequests() {
    console.log("Fetching leave requests for Employee ID:", this.employeeId);

    this.http.get<any[]>(`http://localhost:5000/api/leave/${this.employeeId}`)
      .subscribe(response => {
        this.leaveRequests = response;  // ✅ Assign API response to `leaveRequests`
        console.log("Fetched Leave Requests:", this.leaveRequests);
      }, error => {
        console.error("Error fetching leave requests:", error);
      });
  }
}
